import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);
const express = require('./');

const app = express();
app.set('trust proxy', true);
app.set('foobarquux', true);

const subApp = express();
subApp.get('/', function (req, res) {
  res.send('ok');
});

app.use('/', subApp);

const trust = subApp.get('trust proxy');
const other = subApp.get('foobarquux');

if (trust !== true) {
  console.log('WHOBROKEIT_BUG: expected the mounted app to inherit "trust proxy" = true, but got ' + String(trust) + ' (foobarquux = ' + String(other) + ')');
  process.exitCode = 1;
} else {
  process.exitCode = 0;
}
